import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('eczema-dermatitis',
  kf=["**Atopic eczema** is the commonest form: a chronic, itchy, relapsing inflammatory skin disease with a **barrier defect** and **type 2 (Th2) inflammation**.",
      "Affects up to **20% of children** and 2–10% of adults; about 80% start before age 6.",
      "Infants: cheeks and extensor surfaces; children and adults: **flexures**; chronic disease shows **lichenification**.",
      "UK care follows **NICE CG57 / CKS**: generous emollients, topical steroids matched to severity and site, and treat flares early.",
      "Never miss **eczema herpeticum** (punched-out erosions, unwell): same-day assessment."],
  epi=[{"t": "**Prevalence**", "sub": ["Lifetime prevalence over **15%** in high-income countries; about 230 million people worldwide.", "Affects up to **20% of children** in the UK; 5–15% of young adults still have it."]},
       {"t": "**Age**", "sub": ["Usually starts in **infancy**: about 80% before age 6.", "Typically worst at 2–4 years; may recur in adult life with irritant or occupational exposure."]},
       {"t": "**Atopy**", "sub": ["Clusters with **asthma, hay fever and food allergy** (the atopic march)."]},
       {"t": "**Ethnicity**", "sub": ["All ethnic groups; prevalence and pattern vary between populations (e.g. more extensor and follicular eczema in skin of colour)."]}],
  aet=["**Genetic**: loss-of-function **filaggrin (FLG)** mutations weaken the barrier; strong family history of atopy.",
       "**Irritants**: soaps, detergents, bubble bath, wool, heat, sweating, hard water.",
       "**Allergens**: house dust mite, pets, pollen; food allergy is a trigger in a minority of infants with moderate to severe eczema.",
       "**Infection**: *Staphylococcus aureus* colonisation and flares; herpes simplex.",
       "Stress, hormonal changes, dry winter weather."],
  myths=["**\"It is caused by food allergy\"**: most eczema is not food-driven; avoid restrictive diets without specialist advice.",
         "**\"Steroid creams thin the skin, so avoid them\"**: used correctly (right potency, site and duration) they are safe; steroid phobia undertreats flares.",
         "**\"Eczema is contagious\"**: it is not, although infected eczema can spread bacteria or herpes.",
         "**\"Emollients are optional once the skin looks better\"**: they are the foundation of treatment and should continue."],
  patho_lead="Atopic eczema comes from a **leaky skin barrier** and an **overactive type 2 immune response** that feed each other through the itch–scratch cycle.",
  mech=[("A faulty barrier", "Reduced **filaggrin** and ceramides weaken the stratum corneum, so water escapes (**raised transepidermal water loss**) and the skin becomes dry, rough and easily irritated.", "v3-eczema-barrier-section.jpg", "Healthy barrier (left) vs eczema: gaps between corneocytes let water out and allergens, irritants and bacteria in."),
        ("Allergens and microbes get in", "Irritants, allergens and *S. aureus* penetrate the damaged barrier; keratinocytes release alarmins (**TSLP, IL-33, IL-25**)."),
        ("Type 2 inflammation", "Dendritic cells drive **Th2** cells and ILC2s to release **IL-4, IL-13** and **IL-31**. IL-4/IL-13 further suppress filaggrin and antimicrobial peptides; IgE rises. In chronic eczema Th1, Th17 and Th22 also contribute."),
        ("Itch and scratching", "**IL-31** and other mediators activate itch nerves. Scratching damages the barrier further and releases more alarmins: the **itch–scratch cycle**."),
        ("Chronic changes", "Repeated rubbing thickens the epidermis (**lichenification**), with exaggerated skin markings, excoriations and pigment change.")],
  histo=["**Acute**: spongiosis (intercellular oedema in the epidermis), sometimes vesicles; dermal lymphocytes and eosinophils.",
         "**Subacute**: spongiosis with acanthosis and parakeratosis.",
         "**Chronic**: marked acanthosis, hyperkeratosis and dermal fibrosis (lichen simplex pattern).",
         "Biopsy is rarely needed; consider it when cutaneous T-cell lymphoma or another diagnosis is suspected."],
  special=[{"t": "**Skin of colour**", "sub": ["Redness looks **violaceous, grey or dark brown**, so severity is often underestimated.", "Follicular (papular) and extensor patterns are more common; **post-inflammatory hyper- and hypopigmentation** is marked."]},
           {"t": "**Infants**", "sub": ["Face, scalp and extensors; nappy area usually spared."]},
           {"t": "**Older adults**", "sub": ["Asteatotic (eczema craquelé) and discoid patterns; exclude scabies, drug eruptions and lymphoma."]}],
  comp=["**Bacterial infection** (*S. aureus*, impetiginisation): weeping, crusting, pustules.",
        "**Eczema herpeticum** (HSV): clustered punched-out erosions, fever; an emergency.",
        "Molluscum contagiosum and eczema coxsackium spread more widely.",
        "Sleep loss, poor school or work performance, anxiety and depression.",
        "**Contact dermatitis** (irritant or allergic, including to treatments) and occupational hand eczema.",
        "Erythroderma (rare); growth effects only with very severe disease or excessive steroid use.",
        "Steroid side effects (atrophy, striae, perioral dermatitis) with misuse."],
  prog=["Many children improve with age: in a large meta-analysis about **20% still had eczema 8 years later**, and under 5% at 20 years.",
        "The skin stays dry and sensitive for life; adult relapse is common with irritant exposure.",
        "Earlier onset (before age 2) carries a lower risk of persistence."],
  refs=[("NICE CG57: Atopic eczema in under 12s", "https://www.nice.org.uk/guidance/cg57")],
  see_also=["emollients", "topical-corticosteroids", "hand-eczema", "contact-dermatitis", "itch-xerosis-older-adults"])

E('tinea',
  kf=["**Dermatophyte** infection of keratin (stratum corneum, hair, nails), mostly *Trichophyton rubrum*.",
      "**Asymmetrical** annular plaque with a scaly **active edge** and central clearing; tinea pedis causes macerated toe webs.",
      "Scrape the **edge** for microscopy if uncertain, extensive or before oral treatment.",
      "Topical terbinafine or an imidazole **until 1–2 weeks after clearance**; treat feet and nails (the reservoir).",
      "A topical steroid alone causes **tinea incognito**."],
  epi=[{"t": "**Who**", "sub": ["Worldwide, especially hot humid climates; tinea pedis affects up to 15–25% of adults at some point.", "Tinea corporis is most common in **children and young adults**; tinea cruris and pedis in adult **men**."]},
       {"t": "**Spread**", "sub": ["Skin-to-skin contact, shared towels, bedding and changing rooms; animals (*Microsporum canis* from cats and dogs, *T. verrucosum* from cattle).", "Incubation 1–3 weeks."]}],
  aet=["**Organisms**: anthropophilic *T. rubrum* (most common), *T. interdigitale*, *T. tonsurans*; zoophilic *M. canis*, *T. verrucosum*, *T. erinacei* (hedgehogs) give more inflamed lesions.",
       "**Medical risk factors**: previous tinea, **diabetes**, immunosuppression, hyperhidrosis, obesity, ichthyosis.",
       "**Environment**: occlusive footwear and clothing, sport, crowding, pets, contact sports (tinea gladiatorum).",
       "Emerging **sexually transmitted** *T. mentagrophytes* genotype VII and **terbinafine-resistant** *T. indotineae* (extensive, recalcitrant groin and body tinea, often after travel to South Asia)."],
  myths=["**\"Any ring is ringworm\"**: granuloma annulare, discoid eczema and others make rings; scrape if unsure.",
         "**\"Stop once it looks clear\"**: continue for 1–2 weeks after clearance or it relapses.",
         "**\"A combined steroid cream is best\"**: steroid-antifungal is a short bridge only (up to 7 days) for very inflamed skin."],
  patho_lead="Dermatophytes live only in **dead keratin**; the shape of the rash reflects how they spread and how the host reacts.",
  mech=[("Spores land on skin", "Spores from people, animals, soil or fomites stick to keratinocytes, helped by warmth, moisture and minor trauma."),
        ("Keratin digestion", "Fungi release **keratinases** and proteases to invade the **stratum corneum**, hair and nail; they rarely go deeper because of serum inhibitory factors and host immunity."),
        ("Outward spread", "Hyphae grow outwards, while the host's inflammatory response clears the centre: an **active scaly edge with central clearing**.", "v3-tinea-annular-scrape.jpg", "The ring grows outwards: the most active fungus is at the scaly edge, which is where to scrape."),
        ("Host response decides the look", "Strong cell-mediated immunity (often zoophilic species) gives inflamed, pustular lesions; weak responses (*T. rubrum*, immunosuppression, steroid use) give chronic, widespread, less inflamed disease (**tinea incognito**)."),
        ("Reservoirs and reinfection", "Feet and nails act as reservoirs; scratching and towels spread fungus to the groin and body (**autoinoculation**).")],
  histo=["Fungal hyphae in the stratum corneum (seen with PAS or Grocott stain), sometimes the 'sandwich sign' between orthokeratotic and parakeratotic layers.",
         "Mild spongiosis and a superficial perivascular infiltrate; neutrophils in the stratum corneum.",
         "In practice, diagnosis is by **skin scrapings** (microscopy with KOH and culture or PCR), not biopsy."],
  special=[{"t": "**Skin of colour**", "sub": ["Edges may look grey, violaceous or hyperpigmented rather than red; post-inflammatory pigmentation is common."]},
           {"t": "**Children**", "sub": ["Tinea corporis and capitis are commonest; check pets and family members."]},
           {"t": "**Diabetes and immunosuppression**", "sub": ["Treat tinea pedis promptly: fissured toe webs are a portal for cellulitis."]}],
  comp=["Spread to other sites and household contacts.",
        "**Bacterial superinfection** and cellulitis through fissured toe webs.",
        "**Majocchi granuloma** (follicular invasion, often after steroid use) and **kerion** (scalp).",
        "Id (dermatophytide) reaction: itchy vesicles at a distant site.",
        "Chronic dermatophytosis (T. rubrum at 4 or more sites) and resistant infection."],
  prog=["Usually cured with correct treatment and adherence.",
        "Relapse is common if treatment stops too early or reservoirs (feet, nails, contacts, pets) are not treated."],
  see_also=["onychomycosis", "candida-intertrigo", "annular-rashes", "intertrigo"])

E('cellulitis-erysipelas',
  kf=["Acute bacterial infection of the **dermis and subcutis** (cellulitis) or **upper dermis and lymphatics** (erysipelas).",
      "Usually *Streptococcus pyogenes* (about two thirds) or *Staphylococcus aureus* (about one third).",
      "Typically **one** hot, red, swollen, tender leg; bilateral red legs are rarely cellulitis.",
      "UK: **NICE NG141**; flucloxacillin 500 mg–1 g QDS for 5–7 days for most adults; mark the border and review at 2–3 days.",
      "Emergency if **necrotising fasciitis** or sepsis is possible."],
  epi=[{"t": "**Common**", "sub": ["One of the commonest reasons for antibiotic prescribing in primary care and for emergency admission with skin disease."]},
       {"t": "**Who**", "sub": ["All ages; more common in **middle-aged and older adults**.", "Erysipelas is more common in older adults and infants."]},
       {"t": "**Recurrence**", "sub": ["Up to about a third have a further episode, especially with lymphoedema, venous disease or untreated tinea pedis."]}],
  aet=["**Portal of entry**: toe-web **tinea pedis** or fissured heels, eczema, ulcers, trauma, bites, surgical wounds, IV drug use.",
       "**Host factors**: previous cellulitis, **lymphoedema**, venous insufficiency, **obesity**, diabetes, immunosuppression, chronic kidney or liver disease, pregnancy, alcohol excess.",
       "**Organisms in special settings**: *Pasteurella* (cat or dog bites), *Pseudomonas* (puncture wounds of the foot), *Vibrio* or *Aeromonas* (salt or fresh water), MRSA, Gram-negatives in the immunocompromised."],
  myths=["**\"It was a spider bite\"**: documented spider bites rarely cause cellulitis; look for tinea pedis or a skin break.",
         "**\"Still red on day 3, so the antibiotic failed\"**: redness takes days to settle; check the border and the patient.",
         "**\"Cellulitis is contagious\"**: it is not usually spread person to person."],
  patho_lead="Bacteria cross a **breach in the skin**, multiply in the dermis and trigger an acute inflammatory response.",
  mech=[("A breach in the barrier", "A fissure, cut, bite, ulcer or **macerated toe web** lets skin flora into the dermis; lymphoedema and venous stasis impair clearance."),
        ("Bacteria multiply and spread", "Streptococci release hyaluronidase, streptokinase and DNases that help them spread through tissue planes; staphylococci form local abscesses more often."),
        ("Depth decides the edge", "**Erysipelas** involves the upper dermis and lymphatics, giving a raised, sharp edge; **cellulitis** extends into deep dermis and fat, so the edge is flat and ill-defined.", "v3-cellulitis-depth.jpg", "Erysipelas (left) in the upper dermis and lymphatics vs cellulitis (right) in the deep dermis and fat."),
        ("Inflammation", "Cytokines (TNF, IL-1, IL-6) cause the **redness, heat, swelling and pain**, fever and malaise; toxins can cause systemic illness.", "v3-cellulitis-leg.jpg", "Typical cellulitis in one leg, with the portal of entry in a fissured toe web."),
        ("Healing and damage", "Lymphatics damaged by each episode drain less well, increasing oedema and the risk of **recurrence**.")],
  histo=["Dermal oedema, dilated lymphatics and a diffuse neutrophilic infiltrate extending into subcutaneous fat.",
         "Organisms are often scanty; biopsy is not used for diagnosis."],
  special=[{"t": "**Skin of colour**", "sub": ["Redness may be hard to see: rely on warmth, swelling, tenderness and induration, and compare with the other leg."]},
           {"t": "**Children**", "sub": ["Periorbital or facial cellulitis needs a low threshold for same-day assessment."]},
           {"t": "**Pregnancy**", "sub": ["Erythromycin if penicillin allergic (NICE NG141)."]}],
  comp=["**Necrotising fasciitis**, gas gangrene and streptococcal toxic shock.",
        "**Sepsis**; bacteraemia with seeding to bone, joints or heart valves (endocarditis).",
        "Abscess formation; lymphangitis.",
        "**Recurrent cellulitis** and secondary **lymphoedema**.",
        "Orbital cellulitis with visual loss or cavernous sinus thrombosis (facial infection)."],
  prog=["Most cases respond to oral antibiotics without lasting harm; skin can take weeks to look normal.",
        "Recurrence is common; treating portals of entry and oedema reduces it."],
  see_also=["red-leg", "venous-leg-ulcer", "tinea", "boils-carbuncles", "impetigo"])

E('impetigo',
  kf=["Superficial, contagious bacterial skin infection, mostly *Staphylococcus aureus*, sometimes *Streptococcus pyogenes*.",
      "Most common in **young children**; spreads by direct contact.",
      "**Non-bullous**: honey-coloured crusts around the nose and mouth; **bullous**: flaccid blisters from staphylococcal toxin.",
      "UK (NICE NG153): localised and well → **hydrogen peroxide 1% cream**; topical antibiotic if unsuitable; oral flucloxacillin if widespread or unwell.",
      "Stay off school or nursery until lesions crust over or 48 h after starting antibiotics."],
  epi=[{"t": "**Who**", "sub": ["Most common skin infection in children aged **2–5 years**, but any age can be affected.", "More common in warm, humid weather and in crowded living conditions."]},
       {"t": "**Spread**", "sub": ["Highly contagious by direct contact, towels and toys; outbreaks in nurseries, schools and sports teams."]}],
  aet=["**Organisms**: *S. aureus* (most cases in the UK) and *S. pyogenes* (group A streptococcus), alone or together.",
       "**Primary** impetigo on intact skin, or **secondary** impetigo (impetiginisation) on damaged skin: eczema, scabies, insect bites, chickenpox, herpes simplex, trauma, burns.",
       "Risk factors: nasal carriage of *S. aureus*, immunosuppression, diabetes, poor hygiene, crowding, contact sports."],
  myths=["**\"Impetigo means poor hygiene\"**: it is very common in clean, healthy children.",
         "**\"Fusidic acid is first line\"**: NICE now favours hydrogen peroxide 1% cream for localised disease to reduce resistance."],
  patho_lead="Intact skin resists these bacteria; a **break in the barrier** lets them attach and multiply in the epidermis.",
  mech=[("Barrier breach and attachment", "Minor trauma, eczema or bites expose **fibronectin** receptors; staphylococcal and streptococcal adhesins (e.g. teichoic acids) bind and colonise the surface."),
        ("Non-bullous impetigo", "Bacteria multiply under the stratum corneum, causing a neutrophilic pustule that ruptures; serum dries into **golden crusts**.", "v3-impetigo-sections.jpg", "Non-bullous impetigo (crusted pustule under the stratum corneum) compared with bullous impetigo (toxin splitting the granular layer)."),
        ("Bullous impetigo", "*S. aureus* phage group II releases **exfoliative toxins A and B**, which cleave **desmoglein 1** in the granular layer, so the upper epidermis lifts into flaccid blisters, even on intact skin."),
        ("Local spread", "Scratching and contact carry bacteria to new sites (autoinoculation) and other people.", "v3-impetigo-face.jpg", "Typical distribution around the nose and mouth.")],
  histo=["Subcorneal pustule with neutrophils and Gram-positive cocci.",
         "Bullous impetigo: cleavage in the **granular layer** with few inflammatory cells (the same level as staphylococcal scalded skin syndrome).",
         "Diagnosis is clinical; swab only if recurrent, extensive, or not responding."],
  special=[{"t": "**Skin of colour**", "sub": ["Erythema is less visible; crusting and post-inflammatory hypo- or hyperpigmentation are prominent."]},
           {"t": "**Newborns**", "sub": ["Bullous impetigo in neonates needs prompt assessment (risk of spread and SSSS)."]}],
  comp=["**Cellulitis**, lymphangitis and bacteraemia.",
        "**Staphylococcal scalded skin syndrome** (young children).",
        "**Ecthyma**: deeper, punched-out ulcers that scar.",
        "Post-streptococcal **glomerulonephritis** (2–6 weeks later) and, rarely, scarlet fever or streptococcal toxic shock.",
        "Post-inflammatory pigment change; scarring is uncommon."],
  prog=["Usually self-limiting; without treatment it heals in about 2–3 weeks, and within about 10 days with treatment.",
        "Recurrence suggests nasal carriage or an untreated underlying skin condition."],
  refs=[("NICE NG153: Impetigo antimicrobial prescribing", "https://www.nice.org.uk/guidance/ng153")],
  see_also=["boils-carbuncles", "folliculitis", "eczema-dermatitis", "cellulitis-erysipelas"])
